-- DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3. For a W1 grade, then insert from seat 36.
-- One ask_aar_snapshots row for ASK 594 and its ask_aar_builders row.
-- READ BY W3 FOR THIS ROW: Wall 11517, 11518, 11521 in full and 11527 (first 1,100 characters) by SQL; audit_log 41391; ask594/w4/notes594.md, card594.md and write594.sql in full; the live function's body md5, v_seats line and grants by SQL; md5sum by W3 on every file named.
-- NOT READ BY W3: the card and the press in W4's thread; W1's grade and readback files.
-- md5_written: 918559fe, the live function body (a database write has no target file). W1 CONFIRMS IT WHEN IT GRADES THIS ROW.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (594, '0', $t$ASK 594: the reserve recorder accepts qwen4max as the failed seat or the reserve$t$,
  $t$A run whose panel or reserve includes qwen4max can use the one judge substitution. Before, the database function odv1_record_panel_substitution held a fixed seat list without qwen4max, so a failed qwen4max seat, or qwen4max as the reserve, made the recorder raise and the run stop instead of seating the reserve. (W4's plan, notes594.md section 1; Wall 11517 item 1.)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write it" at 08:11 CST 2026-11-24, with no engine or child run live (Wall 11521; audit 41391). Database only; no engine or child change. One array literal and its comment in odv1_record_panel_substitution: the seat list v_seats gains 'qwen4max'. Function body md5 58fb41af to 918559feb9f7618c5765b4a5ecbdac65; the write's guard confirmed the base before it wrote. Grants unchanged: EXECUTE for postgres, service_role and lab_seat (read by W3 by SQL on the live function: the body md5, the v_seats line and the grants). How it was found: W3's ASK 593 manual entry carried the limit that the recorder's list did not hold qwen4max while Init Seats could make qwen4max the reserve; the coordinator numbered it ASK 594. W4's search: of every public function that names 'sol62', only the recorder lacked qwen4max; qwen4max was the only seat of the live judge order missing from the list (W1's own check, Wall 11518). The case: run 42071 seated gemini, qwen4max and spark with argon as reserve; had qwen4max failed, the recorder would have raised "failed_seat qwen4max is not a panel seat". Shown by test, read-only, on temporary copies of the old and the new body with a debate id that does not exist (W4, and W1's own run, Wall 11518): qwen4max as the failed seat and as the substitute is refused by the old body and passes the seat check in the new; gemini to argon passes in both; haiku is refused by both. The path: plan and build rev 0 (Wall 11517); W1 PASS (Wall 11518); the press; the write (Wall 11521); W1 readback MATCH (Wall 11527 item 1: reversing the one replacement on the live body gives the graded base 58fb41af, so nothing else changed). IN PART, because the recorder runs only when a panel seat fails: no run has executed since the write (debate_results last row 21:57 CST 2026-11-23), and a normal run does not exercise it. A dry regrade with test_fail_seat qwen4max would show it; that needs the operator's release (notes594.md section 6). Consequence: ASK 591's save refuses a seat that is not on this recorder's list (Wall 11541, 11543), so the list is now also the gate of the judge order page.$t$,
  '11517, 11518, 11521, 11527',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$His press at 08:11 CST 2026-11-24 in W4's thread: "Write it" (as Wall 11521 and audit 41391 give it). W3 did not see the card or the press.$t$::text),
  $j${"answer": "Write it", "source": "Wall 11521; audit 41391 (card cmsg_017ZQamDMHrS6fqMHnQDVo58T5YD3oupa1iz57En2G93Ap)", "thread": "W4", "press_time": "08:11 CST 2026-11-24", "question": "not in the record W3 read (the card is in W4's thread); the card text is ask594/w4/card594.md 3c6f41de"}$j$::jsonb,
  'W4',
  $j${"md5": "2e335824", "path": "ask594/w4/notes594.md", "commit": "fe4df734", "note": "W4's plan and build rev 0, eight headings (W1 PASS Wall 11518)", "source": "md5sum by W3; Wall 11517"}$j$::jsonb,
  $j$[{"md5": "c8b70c45", "path": "ask594/w4/write594.sql", "note": "the write: one guarded replacement in the function definition; refuses unless the live body md5 is 58fb41af", "source": "md5sum by W3; Wall 11517, 11518"}, {"md5": "b2866a3f", "path": "ask594/w4/revert594.sql", "note": "the revert", "source": "md5sum by W3; Wall 11517"}, {"md5": "2e335824", "path": "ask594/w4/notes594.md", "note": "plan and build notes rev 0", "source": "md5sum by W3; Wall 11517"}, {"md5": "3c6f41de", "path": "ask594/w4/card594.md", "note": "the card text", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"copy": "run ask594/w4/revert594.sql b2866a3f: one statement puts the old list back (body 58fb41af). W1's note: the revert does not check the md5 first.", "path": "ask594/w4/revert594.sql", "source": "audit 41391; Wall 11518, 11521; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (plan and build rev 0: live md5 equals the write guard; the anchor occurs once; the search re-run; qwen4max the only seat of the judge order missing; temporary copies of the old body and of the write's new body tested: qwen4max refused by the old, accepted by the new, gemini to argon passes in both, haiku refused by both)", "wall_id": 11518, "md5_graded": "918559fe", "verdict_norm": "PASS", "source": "Wall 11518 (W1 tested the write's new body as a temporary copy and does not print its md5); Wall 11527 item 1 gives the live body as 918559fe and shows it is the graded base with the one replacement. W1 CONFIRMS that the body it graded is 918559fe when it grades this row"}]$j$::jsonb,
  ARRAY['918559fe'], '[41391]'::jsonb,
  $j$[{"kind": "database function", "name": "odv1_record_panel_substitution", "before": "body md5 58fb41af; v_seats without qwen4max", "after": "body md5 918559feb9f7618c5765b4a5ecbdac65; v_seats ends 'sonnet','sol62','qwen4max'; grants unchanged (postgres, service_role, lab_seat)"}]$j$::jsonb,
  $j$[{"name": "test594 (read-only; temporary copies of the old and new body; a debate id that does not exist)", "result": "4 PASS: qwen4max as failed seat (old refuses, new passes the seat check); qwen4max as substitute (old refuses, new passes); control gemini to argon (both pass); control haiku (both refuse). Rerun by W1 with its own temporary copies", "source": "notes594.md section 4; Wall 11517 item 4; Wall 11518 item 5"}]$j$::jsonb,
  $j$[{"seat": "W1", "wall_id": 11527, "result": "MATCH (body md5 918559fe; SECURITY DEFINER kept; grants postgres, service_role, lab_seat unchanged; the qwen4max literal stands as graded; reversing that one replacement on the live body gives 58fb41af, the graded base)"}]$j$::jsonb,
  $j${"case": "UNEXERCISED, and a normal run does not exercise it: the recorder runs only when a panel seat fails. EXPECT on the first run in which a panel seat fails with qwen4max as the failed seat or as the reserve: the substitution is recorded, the reserve is seated and the run does not stop at the recorder. A dry regrade with test_fail_seat qwen4max would show it; it needs the operator's release.", "source": "notes594.md section 6; Wall 11521; the EXPECT is W3's reading"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "not yet at the draft of this row: version 298; part 10.0 v286 still says the list does not hold qwen4max. W3's pairs are manual1123/w3/a594/em_pairs_594_draft1.json c1d6280c (part 10.0, two pairs), not graded and not carded at the draft of this row"}$j$::jsonb,
  'read back', $j$[11517, 11518, 11521, 11527, 11541, 11543]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned, built and wrote ASK 594 on its card", "wall_id": 11521}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
